let particles = [];
let maxParticles = 600;

class AnnihilationParticle {
  constructor(x, y, isExplosion = false) {
    this.x = x;
    this.y = y;
    this.isExplosion = isExplosion;

    let angle = random(TWO_PI);
    let speed = isExplosion ? random(5, 15) : random(1, 4);
    this.vx = cos(angle) * speed;
    this.vy = sin(angle) * speed;

    this.life = 1.0; // 1.0 -> 0.0
    this.decay = isExplosion ? random(0.015, 0.035) : random(0.005, 0.015);

    // Size
    this.size = isExplosion ? random(6, 16) : random(2, 7);

    // Base Color Selection
    let baseColor = 300; // Magenta/Purple default
    if (window.currentChordColor) {
      let chordC = color(window.currentChordColor);
      baseColor = hue(chordC);
    }
    this.hue = (baseColor + random(-25, 25)) % 360;
  }

  update() {
    let lowVal = window.audioLow || 0.0;
    let beatVal = window.beatEnergy || 0.0;

    // Perlin noise flow field deflection
    let noiseVal = noise(this.x * 0.006, this.y * 0.006, frameCount * 0.01);
    let flowAngle = noiseVal * TWO_PI * 2.0;

    let forceX = cos(flowAngle) * 0.25;
    let forceY = sin(flowAngle) * 0.25;

    // 變種特有：低音漩渦磁場偏轉
    if (lowVal > 0.5) {
      let dx = this.x - width/2;
      let dy = this.y - height/2;
      let dist = sqrt(dx*dx + dy*dy) + 1.0;
      // 垂直於中心方向的力 (Tangential Force)
      let tx = -dy / dist;
      let ty = dx / dist;
      let magnetStrength = map(lowVal, 0.5, 1.0, 0.0, 0.85);
      forceX += tx * magnetStrength;
      forceY += ty * magnetStrength;
    }

    this.vx += forceX;
    this.vy += forceY;

    // Limit speed
    let speedLimit = this.isExplosion ? 18 : 6;
    let currSpeed = sqrt(this.vx*this.vx + this.vy*this.vy);
    if (currSpeed > speedLimit) {
      this.vx = (this.vx / currSpeed) * speedLimit;
      this.vy = (this.vy / currSpeed) * speedLimit;
    }

    this.x += this.vx * (1.0 + beatVal * 0.8);
    this.y += this.vy * (1.0 + beatVal * 0.8);

    this.life -= this.decay;
  }

  draw() {
    let midVal = window.audioMid || 0.0;
    colorMode(HSB, 360, 100, 100, 1.0);
    noStroke();

    // 發光半徑隨中音波動
    let glowSize = this.size * (1.0 + midVal * 0.8) * this.life;

    // Particle Core
    fill(this.hue, 85, 95, this.life);
    ellipse(this.x, this.y, glowSize, glowSize);

    // Particle Outer Aura (Glow)
    fill(this.hue, 95, 100, this.life * 0.22);
    ellipse(this.x, this.y, glowSize * 2.2, glowSize * 2.2);
  }

  isDead() { 
    return this.life <= 0;
  }
}

function setup() {
  createCanvas(1280, 720);
  colorMode(HSB, 360, 100, 100, 1.0);
  background(0);
}

function draw() {
  // 建立半透明背景以產生發光拖尾
  background(0, 0, 0, 0.15);

  let beatVal = window.beatEnergy || 0.0;

  // 1. 發射源 (中心發射)
  let emissionRate = int(map(window.audioLow || 0.5, 0, 1, 3, 12));
  for (let i = 0; i < emissionRate; i++) {
    let rx = width / 2 + sin(frameCount * 0.05) * 35;
    let ry = height / 2 + cos(frameCount * 0.05) * 35;
    if (particles.length < maxParticles) {
      particles.push(new AnnihilationParticle(rx, ry, false));
    }
  }

  // 2. 變種特有：拍點觸發的「超新星爆炸」
  if (beatVal > 0.72 && random(1.0) > 0.45) {
    let expX = random(width * 0.15, width * 0.85);
    let expY = random(height * 0.15, height * 0.85);
    let numBurst = int(random(35, 75));
    for (let i = 0; i < numBurst; i++) {
      if (particles.length < maxParticles + 200) {
        particles.push(new AnnihilationParticle(expX, expY, true));
      }
    }
  }

  // 3. 更新與繪製粒子
  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.update();
    p.draw();
    if (p.isDead()) {
      particles.splice(i, 1);
    }
  }
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

